import type { Vec3 } from '../contracts/math';

export const ZERO_VEC: Vec3 = { x: 0, y: 0, z: 0 };
export const UP_VEC: Vec3 = { x: 0, y: 1, z: 0 };
const EPS = 1e-6;

export function vec3(x: number, y: number, z: number): Vec3 {
  return { x, y, z };
}

export function copy(v: Vec3): Vec3 {
  return { x: v.x, y: v.y, z: v.z };
}

export function add(a: Vec3, b: Vec3): Vec3 {
  return { x: a.x + b.x, y: a.y + b.y, z: a.z + b.z };
}

export function sub(a: Vec3, b: Vec3): Vec3 {
  return { x: a.x - b.x, y: a.y - b.y, z: a.z - b.z };
}

export function scale(v: Vec3, s: number): Vec3 {
  return { x: v.x * s, y: v.y * s, z: v.z * s };
}

export function dot(a: Vec3, b: Vec3): number {
  return a.x * b.x + a.y * b.y + a.z * b.z;
}

export function lengthSq(v: Vec3): number {
  return v.x * v.x + v.y * v.y + v.z * v.z;
}

export function length(v: Vec3): number {
  return Math.sqrt(lengthSq(v));
}

export function distance(a: Vec3, b: Vec3): number {
  return length(sub(a, b));
}

export function normalize(v: Vec3): Vec3 {
  const len = length(v);
  return len < EPS ? copy(ZERO_VEC) : scale(v, 1 / len);
}

export function withLength(v: Vec3, target: number): Vec3 {
  return scale(normalize(v), target);
}

export function clampLength(v: Vec3, max: number): Vec3 {
  const len = length(v);
  return len > max && len > EPS ? scale(v, max / len) : copy(v);
}

/** Mirrors the velocity around the surface normal, keeping `restitution` of the incoming speed. */
export function reflect(v: Vec3, normal: Vec3, restitution = 1): Vec3 {
  const n = normalize(normal);
  const along = dot(v, n);
  return add(v, scale(n, -along * (1 + restitution)));
}

export function clamp01(value: number): number {
  return value < 0 ? 0 : value > 1 ? 1 : value;
}
