import type { Vec3 } from '../contracts/math';

export interface BoxZone {
  shape: 'box';
  center: Vec3;
  halfExtents: Vec3;
}

export interface SphereZone {
  shape: 'sphere';
  center: Vec3;
  radius: number;
}

export type TriggerZone = BoxZone | SphereZone;

export interface TriggerBase {
  id: string;
  zone: TriggerZone;
  /** Disabled triggers stay in the field but never fire. */
  enabled?: boolean;
}

/** Elements that fire once per entry and then wait out a cooldown. */
export interface OneShotTriggerBase extends TriggerBase {
  cooldownSeconds?: number;
}

export interface BumperConfig extends OneShotTriggerBase {
  type: 'bumper';
  /** Outward facing normal of the bumper surface. */
  normal: Vec3;
  /** Extra speed added along the normal, m/s. */
  strength: number;
  /** Share of the incoming speed kept after the bounce. */
  restitution?: number;
}

export interface SpringPadConfig extends OneShotTriggerBase {
  type: 'spring-pad';
  /** Vertical launch speed, m/s. */
  strength: number;
  /** Keep the horizontal velocity of the ball (default true). */
  keepHorizontal?: boolean;
}

export interface BoostPadConfig extends OneShotTriggerBase {
  type: 'boost-pad';
  direction: Vec3;
  /** Speed added along the direction, m/s. */
  strength: number;
  maxSpeed?: number;
}

export interface JumpPadConfig extends OneShotTriggerBase {
  type: 'jump-pad';
  verticalStrength: number;
  forwardDirection?: Vec3;
  forwardStrength?: number;
}

export interface TeleporterConfig extends OneShotTriggerBase {
  type: 'teleporter';
  target: Vec3;
  exitDirection?: Vec3;
  exitSpeed?: number;
  /** Keep the incoming speed when no explicit exit speed is set (default true). */
  preserveSpeed?: boolean;
  /** Paired teleporter that must not fire right after this one. */
  linkedId?: string;
}

export interface FanConfig extends TriggerBase {
  type: 'fan';
  direction: Vec3;
  /** Acceleration applied while the ball is inside, m/s^2. */
  acceleration: number;
  falloff?: 'none' | 'linear';
}

export interface ConveyorConfig extends TriggerBase {
  type: 'conveyor';
  direction: Vec3;
  /** Belt speed, m/s. */
  speed: number;
  /** How fast the ball matches the belt, 1/s. */
  grip?: number;
}

export interface IceSurfaceConfig extends TriggerBase {
  type: 'ice-surface';
  friction?: number;
  linearDamping?: number;
  restitution?: number;
}

export interface MudSurfaceConfig extends TriggerBase {
  type: 'mud-surface';
  friction?: number;
  linearDamping?: number;
  restitution?: number;
}

export interface WaterZoneConfig extends TriggerBase {
  /** 'respawn' throws the ball back with a penalty, 'swim' only slows it down. */
  type: 'water-zone';
  mode?: 'respawn' | 'swim';
  penaltyStrokes?: number;
  drag?: number;
  buoyancy?: number;
  respawnPosition?: Vec3;
}

export interface LavaZoneConfig extends TriggerBase {
  type: 'lava-zone';
  penaltyStrokes?: number;
  respawnPosition?: Vec3;
}

export interface KillZoneConfig extends TriggerBase {
  type: 'kill-zone';
  penaltyStrokes?: number;
  respawnPosition?: Vec3;
}

export interface GravityZoneConfig extends TriggerBase {
  type: 'gravity-zone';
  gravity: Vec3;
  /** 'override' replaces world gravity inside the zone, 'additive' stacks on top of it. */
  mode?: 'override' | 'additive';
}

export interface MagnetZoneConfig extends TriggerBase {
  type: 'magnet-zone';
  /** Defaults to the zone center. */
  center?: Vec3;
  /** Acceleration at full strength, m/s^2. */
  strength: number;
  polarity?: 'attract' | 'repel';
  falloff?: 'none' | 'linear';
  maxSpeed?: number;
}

export type TriggerConfig =
  | BumperConfig
  | SpringPadConfig
  | BoostPadConfig
  | JumpPadConfig
  | TeleporterConfig
  | FanConfig
  | ConveyorConfig
  | IceSurfaceConfig
  | MudSurfaceConfig
  | WaterZoneConfig
  | LavaZoneConfig
  | KillZoneConfig
  | GravityZoneConfig
  | MagnetZoneConfig;

export type TriggerKind = TriggerConfig['type'];

export interface SurfaceState {
  friction: number;
  restitution: number;
  linearDamping: number;
}

export type RespawnReason = 'water' | 'lava' | 'kill';

export interface RespawnEffect {
  reason: RespawnReason;
  /** Null when neither the zone nor the caller knows a safe spot. */
  position: Vec3 | null;
  penaltyStrokes: number;
}

export type TriggerPhase = 'enter' | 'stay' | 'exit' | 'fire';

export interface TriggerEvent {
  id: string;
  type: TriggerKind;
  phase: TriggerPhase;
}

/** Result of a single trigger for one simulation step. */
export interface TriggerEffect {
  velocityDelta?: Vec3;
  velocity?: Vec3;
  teleport?: Vec3;
  respawn?: RespawnEffect;
  surface?: SurfaceState;
}

export interface TriggerSample {
  position: Vec3;
  velocity: Vec3;
  radius: number;
  dt: number;
  worldGravity: Vec3;
  safePosition: Vec3 | null;
}

export interface TriggerRuntimeState {
  inside: boolean;
  cooldown: number;
}

export interface TriggerResolution {
  state: TriggerRuntimeState;
  effect: TriggerEffect | null;
  event: TriggerEvent | null;
}
