import type { Vec3 } from '../contracts/math';
import type { TriggerZone } from './types';
import { clamp01, distance } from './vec';

const EPS = 1e-6;

export function zoneCenter(zone: TriggerZone): Vec3 {
  return zone.center;
}

/** True when a ball of `radius` overlaps the zone. */
export function zoneContains(zone: TriggerZone, point: Vec3, radius = 0): boolean {
  if (zone.shape === 'sphere') {
    return distance(point, zone.center) <= zone.radius + radius;
  }
  return (
    Math.abs(point.x - zone.center.x) <= zone.halfExtents.x + radius &&
    Math.abs(point.y - zone.center.y) <= zone.halfExtents.y + radius &&
    Math.abs(point.z - zone.center.z) <= zone.halfExtents.z + radius
  );
}

/** 1 at the zone center, 0 at its border. Used for force falloff. */
export function zoneNormalizedDepth(zone: TriggerZone, point: Vec3): number {
  if (zone.shape === 'sphere') {
    if (zone.radius <= EPS) return 0;
    return clamp01(1 - distance(point, zone.center) / zone.radius);
  }
  const h = zone.halfExtents;
  const dx = h.x > EPS ? 1 - Math.abs(point.x - zone.center.x) / h.x : 1;
  const dy = h.y > EPS ? 1 - Math.abs(point.y - zone.center.y) / h.y : 1;
  const dz = h.z > EPS ? 1 - Math.abs(point.z - zone.center.z) / h.z : 1;
  return clamp01(Math.min(dx, dy, dz));
}
